"""ICMP and ICMPv6 alone and inside IPv6, on dpkt's vectors and generated bytes."""

import importlib.util
import subprocess
import sys
import unittest
from pathlib import Path

import octetrail
from octetrail import NeedData, icmp, icmp6, ip6

ROOT = Path(__file__).resolve().parents[2]
SPEC = importlib.util.spec_from_file_location("icmp_fixture", ROOT / "tools/icmp_differential.py")
F = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(F)
CASES = {k: bytes.fromhex(h) for k, (_, h) in F.cases().items()}


class IcmpTests(unittest.TestCase):
    def test_every_case_runs(self):
        report = F.exercise(octetrail)
        self.assertEqual(set(report["cases"]), set(CASES))
        for name in ("icmp_echo", "icmp6_unreach", "ip6_icmp6_error", "ip6_icmp_echo"):
            self.assertNotIn("error", report["cases"][name], name)

    def test_dpkt_vectors(self):
        raw = bytes.fromhex(F.UNREACH_DPKT)
        self.assertEqual(bytes(icmp.ICMP(raw)), raw)
        echo = icmp.ICMP(type=0, data=icmp.ICMP.Echo(id=1, seq=0x03D6, data=F.ECHO_DATA))
        self.assertEqual(bytes(echo), CASES["icmp_echo_reply"])
        self.assertEqual(echo.sum, 0x5387)

    def test_dispatch_aliases_and_fallback(self):
        message = icmp.ICMP(CASES["icmp_echo"])
        self.assertIs(message.echo, message.data)
        self.assertEqual((message.echo.id, message.echo.seq, message.echo.data), (1, 2, b"ping"))
        self.assertEqual(icmp.ICMP(CASES["icmp_unknown_type"]).data, b"abcd")
        self.assertEqual(icmp.ICMP(CASES["icmp_unreach_short_quote"]).data[:4], b"\0\0\x05\xdc")
        with self.assertRaises(NeedData):
            icmp.ICMP(CASES["icmp_short"])

    def test_icmp6_errors_quote_ipv6(self):
        message = icmp6.ICMP6(CASES["icmp6_too_big"])
        self.assertEqual(message.toobig.mtu, 1280)
        self.assertIsInstance(message.toobig.ip6, ip6.IP6)
        self.assertEqual(message.toobig.ip6.data, b"note")
        self.assertEqual(icmp6.ICMP6(CASES["icmp6_time_exceed_cut"]).data[:4], bytes(4))
        with self.assertRaises(NeedData):
            icmp6.ICMP6(CASES["icmp6_short"])

    def test_quote_with_fragment_offset_error_stays_bytes(self):
        raw = bytes.fromhex(F.FRAGMENT_AFTER_AH)
        message = icmp6.ICMP6(raw)
        self.assertEqual(type(message.data), bytes)
        self.assertEqual(message.data, raw[4:])
        self.assertEqual(bytes(message), raw)
        with self.assertRaises(ip6.FragmentOffsetError) as result:
            ip6.IP6(raw[8:])
        self.assertIsInstance(result.exception, AttributeError)

    def test_ipv6_decodes_and_checksums_icmp6(self):
        packet = ip6.IP6(CASES["ip6_icmp6_error"])
        self.assertIs(packet.icmp6, packet.data)
        self.assertIsInstance(ip6.IP6(CASES["ip6_icmp_echo"]).icmp, icmp.ICMP)
        built = ip6.IP6(nxt=58, data=icmp6.ICMP6(type=128, data=icmp6.ICMP6.Echo(id=7)))
        bytes(built)
        self.assertNotEqual(built.data.sum, 0)

    def test_optimized_probe_rejects_wrong_provider_version(self):
        result = subprocess.run(
            [
                sys.executable,
                "-B",
                "-I",
                "-O",
                ROOT / "tools/icmp_differential.py",
                "--probe",
                "--module",
                "octetrail",
                "--version",
                "9.9.9",
            ],
            capture_output=True,
            text=True,
            check=False,
        )
        self.assertNotEqual(result.returncode, 0)
        self.assertIn("wrong provider version", result.stderr)


if __name__ == "__main__":
    unittest.main()
